DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.hc_action(uuid,uuid,uuid,text,jsonb)'::regprocedure) INTO definition; IF position('File integrity mismatch' in definition)=0 THEN RAISE EXCEPTION 'Integrity guard missing'; END IF; definition := replace(definition, 'now()', 'clock_timestamp()'); EXECUTE definition; END $$;
CREATE FUNCTION public.hc_device_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.owner_id::text,0)); IF (SELECT count(*) FROM public.hc_devices WHERE owner_id=NEW.owner_id AND revoked_at IS NULL)>=12 THEN RAISE EXCEPTION 'Active device limit reached'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hc_device_limit BEFORE INSERT ON public.hc_devices FOR EACH ROW EXECUTE FUNCTION public.hc_device_limit();